param([switch]$NoClient)
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false)
$base=[IO.Path]::GetFullPath($PSScriptRoot);$utf8=New-Object Text.UTF8Encoding($false)
foreach($folder in @('config','data','logs','temp','cache','downloads','runtime')){[IO.Directory]::CreateDirectory((Join-Path $base $folder))|Out-Null}
$env:TEMP=Join-Path $base 'temp';$env:TMP=$env:TEMP;$env:STUDYDESK_ROOT=$base
Set-Location -LiteralPath $base
$env:PLAYWRIGHT_BROWSERS_PATH=Join-Path $base 'runtime\browsers'
function Status([string]$message){[Console]::WriteLine($message)}
function Write-Atomic([string]$path,[string]$content){$tmp=$path+'.new';[IO.File]::WriteAllText($tmp,$content,$utf8);if(Test-Path -LiteralPath $path){[IO.File]::Replace($tmp,$path,($path+'.previous'));[IO.File]::Delete($path+'.previous')}else{[IO.File]::Move($tmp,$path)}}
function Random-Hex { $bytes=New-Object byte[] 24;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($bytes)}finally{$rng.Dispose()};return ([BitConverter]::ToString($bytes)).Replace('-','').ToLowerInvariant() }
function Free-Port { $listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Loopback,0);$listener.Start();try{return $listener.LocalEndpoint.Port}finally{$listener.Stop()} }
function Port-Busy([int]$port){$client=New-Object Net.Sockets.TcpClient;try{$task=$client.ConnectAsync('127.0.0.1',$port);return ($task.Wait(600) -and $client.Connected)}catch{return $false}finally{$client.Dispose()}}
function Native-Quote([string]$value){return '"'+[regex]::Replace([regex]::Replace($value,'(\\*)"','$1$1\"'),'(\\+)$','$1$1')+'"'}
function Run-Tool([string]$exe,[string[]]$arguments,[string]$label){$info=New-Object Diagnostics.ProcessStartInfo;$info.FileName=$exe;$info.Arguments=($arguments|ForEach-Object {Native-Quote $_}) -join ' ';$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.WindowStyle='Hidden';$info.WorkingDirectory=$base;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$info.StandardOutputEncoding=$utf8;$info.StandardErrorEncoding=$utf8;$process=New-Object Diagnostics.Process;$process.StartInfo=$info;[void]$process.Start();$out=$process.StandardOutput.ReadToEndAsync();$err=$process.StandardError.ReadToEndAsync();$process.WaitForExit();[IO.File]::WriteAllText((Join-Path $base ('logs\'+$label+'.log')),($out.Result+"`r`n"+$err.Result),$utf8);return $process.ExitCode}
function Download-Verified($item,[string]$name){$target=Join-Path $base ('downloads\'+$name);if((Test-Path -LiteralPath $target) -and (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant() -eq $item.sha256){return $target};Status ('正在下载并校验 '+$name);$curl=Join-Path $env:WINDIR 'System32\curl.exe';if(-not(Test-Path -LiteralPath $curl)){throw '缺少Windows curl下载工具，请更新Windows 10/11系统'};if((Run-Tool $curl @('--fail','--location','--retry','3','--connect-timeout','30','--output',($target+'.part'),'--url',$item.url) ('download-'+$name)) -ne 0){throw ('下载未完成，请检查网络后重试：'+$name)};if((Get-FileHash -LiteralPath ($target+'.part') -Algorithm SHA256).Hash.ToLowerInvariant() -ne $item.sha256){throw ('下载文件SHA256不匹配，已停止：'+$name)};Move-Item -LiteralPath ($target+'.part') -Destination $target -Force;return $target}
function Expand-Safe([string]$archive,[string]$destination,[bool]$basicNode=$false){Add-Type -AssemblyName System.IO.Compression.FileSystem;[IO.Directory]::CreateDirectory($destination)|Out-Null;$root=[IO.Path]::GetFullPath($destination)+[IO.Path]::DirectorySeparatorChar;$zip=[IO.Compression.ZipFile]::OpenRead($archive);try{foreach($entry in $zip.Entries){if($basicNode -and $entry.FullName -notmatch '^[^/]+/(node[.]exe|LICENSE|README[.]md)$'){continue};$name=$entry.FullName.Replace('/',[IO.Path]::DirectorySeparatorChar);$path=[IO.Path]::GetFullPath((Join-Path $destination $name));if(-not $path.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw '压缩包路径越界，已停止'};if($entry.FullName.EndsWith('/')){[IO.Directory]::CreateDirectory($path)|Out-Null}else{[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))|Out-Null;[IO.Compression.ZipFileExtensions]::ExtractToFile($entry,$path,$true)}}}finally{$zip.Dispose()}}
function Runtime-Zip($item,[string]$name,[string]$folder,[string]$probe){$destination=Join-Path $base ('runtime\'+$folder);if((Test-Path -LiteralPath (Join-Path $destination $probe)) -and (Test-Path -LiteralPath (Join-Path $destination '.installed-sha256')) -and ([IO.File]::ReadAllText((Join-Path $destination '.installed-sha256')).Trim() -eq $item.sha256)){return};$archive=Download-Verified $item $name;$staging=Join-Path $base ('temp\extract-'+[Guid]::NewGuid().ToString('N'));Expand-Safe $archive $staging ($folder -eq 'node');$top=Join-Path $staging $item.top;if(-not(Test-Path -LiteralPath (Join-Path $top $probe))){throw ('官方运行时目录不符合预期：'+$name)};if(Test-Path -LiteralPath $destination){Copy-Item -Path (Join-Path $top '*') -Destination $destination -Recurse -Force}else{Move-Item -LiteralPath $top -Destination $destination};[IO.File]::WriteAllText((Join-Path $destination '.installed-sha256'),$item.sha256,$utf8); $resolved=[IO.Path]::GetFullPath($staging);if(-not $resolved.StartsWith(([IO.Path]::GetFullPath((Join-Path $base 'temp'))+[IO.Path]::DirectorySeparatorChar),[StringComparison]::OrdinalIgnoreCase)){throw '临时目录检查失败'};Remove-Item -LiteralPath $resolved -Recurse -Force}
function Test-Database { $out=Join-Path $base 'temp\db-probe.log';$err=Join-Path $base 'temp\db-probe.err';$arguments=@(('--defaults-extra-file='+$base.Replace('\','/')+'/config/root-client.ini'),'--connect-timeout=2','--default-character-set=utf8mb4','--raw','--batch','--skip-column-names','--execute=SELECT @@datadir');$p=Start-Process -FilePath (Join-Path $base 'runtime\database\bin\mariadb.exe') -ArgumentList (($arguments|ForEach-Object {Native-Quote $_}) -join ' ') -WindowStyle Hidden -Wait -PassThru -RedirectStandardOutput $out -RedirectStandardError $err;if($p.ExitCode -ne 0){return $false};$actual=[IO.File]::ReadAllText($out,$utf8).Trim().Replace('/','\').TrimEnd('\');$expected=[IO.Path]::GetFullPath((Join-Path $base 'data\database')).TrimEnd('\');return $actual -eq $expected }
function Test-Backend {try{$response=Invoke-WebRequest -UseBasicParsing ('http://127.0.0.1:'+$script:state.httpPort+'/local/status') -TimeoutSec 3;$result=[Text.Encoding]::UTF8.GetString($response.RawContentStream.ToArray())|ConvertFrom-Json;return $result.service -eq 'SuperAutoStudy' -and $result.database -eq 'ok' -and $result.installationId -eq $script:state.installationId -and $result.installationRoot -eq $base}catch{return $false}}
$hash=[Security.Cryptography.SHA256]::Create();try{$id=([BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($base.ToUpperInvariant())))).Replace('-','').Substring(0,24)}finally{$hash.Dispose()}
$newJava=$null
$lock=New-Object Threading.Mutex($false,('Local\StudentTongStart-'+$id));$held=$false
try{
 try{$held=$lock.WaitOne(600000)}catch [Threading.AbandonedMutexException]{$held=$true};if(-not $held){throw '其他启动进程仍在配置，请稍后重试'}
 if(-not [Environment]::Is64BitOperatingSystem){throw '本安装包需要Windows 10/11 64位系统'}
 $manifest=Get-Content -LiteralPath (Join-Path $base 'runtime-manifest.json') -Raw|ConvertFrom-Json
 Status '正在检查本机运行环境'
 if(-not(Test-Path "$env:WINDIR\System32\vcruntime140.dll") -or -not(Test-Path "$env:WINDIR\System32\msvcp140.dll") -or -not(Test-Path "$env:WINDIR\System32\vcruntime140_1.dll")){
  $vc=Download-Verified $manifest.vcRuntime 'vc_redist.x64.exe';$signature=Get-AuthenticodeSignature -LiteralPath $vc;if($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation'){throw '微软运行库数字签名验证失败'};Status '需要Windows授权安装微软VC++运行库';$process=Start-Process -FilePath $vc -ArgumentList '/install /passive /norestart' -Verb RunAs -WindowStyle Hidden -Wait -PassThru;if($process.ExitCode -notin @(0,1638,3010)){throw '微软运行库安装未完成，请查看系统安装提示'}
 }
 Runtime-Zip $manifest.java 'java8.zip' 'java' 'bin\java.exe'
 Runtime-Zip $manifest.database 'mariadb.zip' 'database' 'bin\mariadbd.exe'
 Runtime-Zip $manifest.node 'node.zip' 'node' 'node.exe'
 $node=Join-Path $base 'runtime\node\node.exe';$java=Join-Path $base 'runtime\java\bin\java.exe';$db=Join-Path $base 'runtime\database\bin'
 # Trust the user's existing Windows certificate stores without disabling TLS verification.
 $certificates=New-Object Text.StringBuilder
 foreach($location in @('CurrentUser','LocalMachine')){foreach($storeName in @('Root','CA')){$store=New-Object Security.Cryptography.X509Certificates.X509Store($storeName,$location);try{$store.Open('ReadOnly');foreach($cert in $store.Certificates){[void]$certificates.AppendLine('-----BEGIN CERTIFICATE-----');[void]$certificates.AppendLine([Convert]::ToBase64String($cert.RawData,[Base64FormattingOptions]::InsertLineBreaks));[void]$certificates.AppendLine('-----END CERTIFICATE-----')}}finally{$store.Close()}}}
 $env:NODE_EXTRA_CA_CERTS=Join-Path $base 'cache\windows-trust.pem';[IO.File]::WriteAllText($env:NODE_EXTRA_CA_CERTS,$certificates.ToString(),$utf8)
 $cli=Join-Path $base 'runtime\vision-node\node_modules\playwright\cli.js'
 $browserInfo=Join-Path $base 'config\browser-path.txt';$browser=''
 if(Test-Path -LiteralPath $browserInfo){$browser=Join-Path $base ([IO.File]::ReadAllText($browserInfo,$utf8).Trim())}
 if(-not $browser -or -not(Test-Path -LiteralPath $browser)){
  Status '正在安装浏览器环境（首次需要联网，请耐心等待）'
  if((Run-Tool $node @($cli,'install','chromium','--no-shell','--no-progress') 'browser-install') -ne 0){throw '浏览器自动下载未完成，请检查网络后重试；已保留下载进度'}
  $script="const p=require('./runtime/vision-node/node_modules/playwright'),path=require('path');process.stdout.write(Buffer.from(path.relative(process.cwd(),p.chromium.executablePath()),'utf8').toString('base64'));"
  $encoded=& $node '-e' $script;if($LASTEXITCODE -ne 0){throw '浏览器位置检查失败'};$relative=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($encoded -join '').Trim()));$browser=Join-Path $base $relative;if(-not(Test-Path -LiteralPath $browser)){throw '浏览器安装未通过文件检查'};Write-Atomic $browserInfo $relative
 }
 $env:STUDYDESK_BROWSER_BINARY=$browser
 $stateFile=Join-Path $base 'config\portable-state.json'
 if(Test-Path -LiteralPath $stateFile){$script:state=Get-Content -LiteralPath $stateFile -Raw|ConvertFrom-Json;if($state.schema -ne 1){throw '本机配置版本不受支持，原数据已保留'}}else{$httpPort=Free-Port;$dbPort=Free-Port;while($dbPort -eq $httpPort){$dbPort=Free-Port};$script:state=[pscustomobject]@{schema=1;installationId=[Guid]::NewGuid().ToString();httpPort=$httpPort;dbPort=$dbPort;rootPassword=(Random-Hex);appPassword=(Random-Hex);databaseCreated=$false;bootstrapComplete=$false};Write-Atomic $stateFile ($state|ConvertTo-Json)}
 Write-Atomic (Join-Path $base 'config\instance-id.txt') $state.installationId
 if(Test-Backend){Status '本机服务已就绪'}else{
  if(-not (Test-Database)){
   $pidFile=Join-Path $base 'logs\database.pid';$owned=$null;if(Test-Path -LiteralPath $pidFile){$processId=[int]([IO.File]::ReadAllText($pidFile).Trim());$owned=Get-Process -Id $processId -ErrorAction SilentlyContinue;if($owned -and $owned.Path -ne (Join-Path $db 'mariadbd.exe')){$owned=$null}}
   if($owned){throw '本目录数据库进程仍在启动或认证失败，请检查logs/database.err；没有启动第二个数据库'}
   if(Port-Busy $state.dbPort){$state.dbPort=Free-Port;Write-Atomic $stateFile ($state|ConvertTo-Json)}
   if(-not $state.databaseCreated){Status '正在创建本机空数据库';$data=Join-Path $base 'data\database';if((Test-Path -LiteralPath $data) -and (Get-ChildItem -LiteralPath $data -Force|Select-Object -First 1)){throw '检测到尚未完成的数据库初始化，已保留现有数据，请查看日志，不会自动清空'};if((Run-Tool (Join-Path $db 'mariadb-install-db.exe') @(("--datadir=$data"),("--port=$($state.dbPort)"),'--silent') 'database-initialize') -ne 0){throw '数据库初始化失败，请查看logs/database-initialize.log'};$state.databaseCreated=$true;Write-Atomic $stateFile ($state|ConvertTo-Json)}
   $folder=$base.Replace('\','/');$dbIni="[mysqld]`nbasedir=$folder/runtime/database`ndatadir=$folder/data/database`nport=$($state.dbPort)`nbind-address=127.0.0.1`ncharacter-set-server=utf8mb4`nmax_connections=40`ninnodb_buffer_pool_size=64M`nlog_error=$folder/logs/database.err`n"
   $setupFile=Join-Path $base 'config\setup-once.sql'
   if(-not $state.bootstrapComplete){$schema=[IO.File]::ReadAllText((Join-Path $base 'setup\schema.sql'),$utf8);$tables=[regex]::Matches($schema,'(?s)CREATE TABLE\s.*?;')|ForEach-Object {[regex]::Replace($_.Value.Replace('CREATE TABLE','CREATE TABLE IF NOT EXISTS'),'\s+',' ')};$sql=@("ALTER USER 'root'@'localhost' IDENTIFIED BY '$($state.rootPassword)';","CREATE DATABASE IF NOT EXISTS tihai CHARACTER SET utf8mb4;","CREATE USER IF NOT EXISTS 'studenttong'@'127.0.0.1' IDENTIFIED BY '$($state.appPassword)';","GRANT ALL ON tihai.* TO 'studenttong'@'127.0.0.1';",'USE tihai;')+$tables;[IO.File]::WriteAllText($setupFile,($sql -join "`n"),$utf8);$dbIni+="init_file=$folder/config/setup-once.sql`n"}
   Write-Atomic (Join-Path $base 'config\database.ini') $dbIni
   Write-Atomic (Join-Path $base 'config\root-client.ini') "[client]`nhost=127.0.0.1`nport=$($state.dbPort)`nuser=root`npassword=$($state.rootPassword)`nprotocol=tcp`n"
   Status '正在启动本目录数据库';$process=Start-Process -FilePath (Join-Path $db 'mariadbd.exe') -ArgumentList (Native-Quote ('--defaults-file='+$folder+'/config/database.ini')) -WorkingDirectory $base -WindowStyle Hidden -PassThru;[IO.File]::WriteAllText((Join-Path $base 'logs\database.pid'),[string]$process.Id,$utf8)
   $ready=$false;for($i=0;$i -lt 60;$i++){Start-Sleep -Milliseconds 500;if(Test-Database){$ready=$true;break};$process.Refresh();if($process.HasExited){break}};if(-not $ready){throw '数据库启动未通过认证检查，请查看logs/database.err'}
  }
  if(Port-Busy $state.httpPort){$state.httpPort=Free-Port;Write-Atomic $stateFile ($state|ConvertTo-Json)}
  $template=[IO.File]::ReadAllText((Join-Path $base 'setup\application-local.template.yml'),$utf8).Replace('__HTTP_PORT__',[string]$state.httpPort).Replace('__DB_PORT__',[string]$state.dbPort).Replace('__DB_PASSWORD__',$state.appPassword)
  Write-Atomic (Join-Path $base 'config\application-local.yml') $template
  $folder=$base.Replace('\','/');$arguments=@(("-Djava.io.tmpdir=$folder/temp"),("-Duser.home=$folder/cache"),'-Dfile.encoding=UTF-8','-Djavax.net.ssl.trustStoreType=Windows-ROOT','-Djavax.net.ssl.trustStore=NONE',("-Dstudenttong.root=$folder"),'-jar',("$folder/target/SuperAuto-1.0-SNAPSHOT.jar"),'--spring.profiles.active=local',("--spring.config.additional-location=file:$folder/config/"),'--spring.cloud.bootstrap.enabled=false')
  Status '正在启动学习工作台';$process=Start-Process -FilePath $java -ArgumentList (($arguments|ForEach-Object {Native-Quote $_}) -join ' ') -WorkingDirectory $base -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $base 'logs\application.out.log') -RedirectStandardError (Join-Path $base 'logs\application.err.log');[IO.File]::WriteAllText((Join-Path $base 'logs\application.pid'),[string]$process.Id,$utf8)
  $newJava=$process;$ready=$false;for($i=0;$i -lt 120;$i++){Start-Sleep -Milliseconds 750;if(Test-Backend){$ready=$true;break};$process.Refresh();if($process.HasExited -or ((Test-Path (Join-Path $base 'logs\application.out.log')) -and (Select-String -LiteralPath (Join-Path $base 'logs\application.out.log') -Pattern 'APPLICATION FAILED TO START|Application run failed' -Quiet))){break}};if(-not $ready){throw '本机工作台启动失败，请查看logs/application.out.log'}
  $state.bootstrapComplete=$true;Write-Atomic $stateFile ($state|ConvertTo-Json);if(Test-Path -LiteralPath (Join-Path $base 'config\setup-once.sql')){Remove-Item -LiteralPath (Join-Path $base 'config\setup-once.sql') -Force}
 }
 $state.bootstrapComplete=$true;Write-Atomic $stateFile ($state|ConvertTo-Json);if(Test-Path -LiteralPath (Join-Path $base 'config\setup-once.sql')){Remove-Item -LiteralPath (Join-Path $base 'config\setup-once.sql') -Force}
 $env:STUDYDESK_SERVICE_URL='http://127.0.0.1:'+$state.httpPort
 Write-Atomic (Join-Path $base 'logs\startup-result.json') (@{ready=$true;installationId=$state.installationId;httpPort=$state.httpPort;dbPort=$state.dbPort;root=$base;version='0.3.0';time=(Get-Date -Format o)}|ConvertTo-Json)
 Status ('READY '+$env:STUDYDESK_SERVICE_URL)
 if(-not $NoClient){try{$desktop=[Environment]::GetFolderPath('DesktopDirectory');$shortcut=Join-Path $desktop '学生通.lnk';$shell=New-Object -ComObject WScript.Shell;if(Test-Path -LiteralPath $shortcut){$existing=$shell.CreateShortcut($shortcut);if($existing.TargetPath -ne (Join-Path $base '启动学生通.cmd')){$shortcut=Join-Path $desktop '学生通0.3.lnk'}};if(-not(Test-Path -LiteralPath $shortcut)){$link=$shell.CreateShortcut($shortcut);$link.TargetPath=Join-Path $base '启动学生通.cmd';$link.WorkingDirectory=$base;$link.IconLocation=Join-Path $base 'client\StudyDesk.ico';$link.Save()}}catch{Status '桌面快捷方式未创建，可从安装目录启动'};Start-Process -FilePath (Join-Path $base 'client\StudyDesk.exe') -WorkingDirectory (Join-Path $base 'client') -WindowStyle Normal}
}catch{if($newJava){$newJava.Refresh();if(-not $newJava.HasExited){$newJava.Kill()}};[IO.File]::WriteAllText((Join-Path $base 'logs\startup-error.log'),($_|Out-String),$utf8);Write-Output ('配置或启动失败：'+$_.Exception.Message);exit 1}finally{if($held){$lock.ReleaseMutex()};$lock.Dispose()}
exit 0
